<template>
 <view class="events">
  <view class="section-head"><view class="heading-copy"><text class="eyebrow">BLESS TOGETHER</text><text class="heading">{{ section==='mine'?c.myEvents:c.title }}</text></view><button class="mine-button" @click="switchSection"><uni-icons :type="section==='mine'?'left':'person'" size="17" color="#8d713b"/><text>{{ section==='mine'?c.discover:c.myEvents }}</text></button></view>
  <text class="lead">{{ section==='mine'?c.joinHint:c.intro }}</text>
  <view v-if="section==='mine'">
   <view v-if="!signedIn" class="state"><uni-icons type="person" size="36" color="#c2a052"/><text>{{ c.signIn }}</text><button @click="login">{{ c.signIn }}</button></view>
   <view v-else-if="mineLoading && !joined.length" class="state">{{ c.loading }}</view>
   <view v-else-if="mineFailed && !joined.length" class="state"><text>{{ c.error }}</text><button @click="loadMine">{{ c.retry }}</button></view>
   <view v-else-if="!joined.length" class="state"><uni-icons type="chatbubble" size="36" color="#c2a052"/><text>{{ c.noJoined }}</text><button @click="section='discover'">{{ c.explore }}</button></view>
   <view v-else class="cards"><button v-for="item in joined" :key="item.id" class="event-row" :disabled="!item.available" @click="open(item,true)"><image :src="item.cover" mode="aspectFill"/><view class="copy"><text class="status">{{ item.available?c[item.phase]:c.offline }}</text><text class="card-title">{{ item.title }}</text><text class="meta">{{ item.myPosts }} {{ c.postCount }}</text><text class="row-link">{{ item.available?c.viewMyPosts:c.offline }} <text v-if="item.available">↗</text></text></view></button></view>
   <button v-if="joined.length && (mineFailed || joined.length < mineTotal)" class="load-more" :disabled="mineLoading" @click="loadMine">{{ mineLoading?c.loading:mineFailed?c.retry:c.more }}</button>
  </view>
  <view v-else>
   <view v-if="loading" class="state">{{ c.loading }}</view>
   <view v-else-if="failed" class="state"><text>{{ c.error }}</text><button @click="load">{{ c.retry }}</button></view>
   <view v-else>
    <view v-if="featured.length" class="featured-section">
     <view class="block-heading"><text>{{ c.featured }}</text><text class="count">{{ featuredIndex+1 }} / {{ featured.length }}</text></view>
     <swiper v-if="featured.length>1" class="featured-swiper" :current="featuredIndex" :autoplay="false" :circular="false" @change="featuredIndex=$event.detail.current"><swiper-item v-for="item in featured" :key="item.id"><button class="hero-card" @click="open(item)"><image :src="item.cover" mode="aspectFill"/><view class="hero-shade"/><view class="hero-top"><text class="hero-status">{{ c[item.phase] }}</text><view class="heat" @tap.stop="explainHeat"><uni-icons type="fire-filled" size="15" color="#f3dc9e"/><text>{{ item.stats.heat }}</text></view></view><view class="hero-copy"><text class="hero-title">{{ item.title }}</text><text class="hero-summary">{{ item.summary }}</text><view class="hero-bottom"><text>{{ item.stats.participants }} {{ c.participants }}</text></view></view></button></swiper-item></swiper>
     <button v-else class="hero-card" @click="open(featured[0])"><image :src="featured[0].cover" mode="aspectFill"/><view class="hero-shade"/><view class="hero-top"><text class="hero-status">{{ c[featured[0].phase] }}</text><view class="heat" @tap.stop="explainHeat"><uni-icons type="fire-filled" size="15" color="#f3dc9e"/><text>{{ featured[0].stats.heat }}</text></view></view><view class="hero-copy"><text class="hero-title">{{ featured[0].title }}</text><text class="hero-summary">{{ featured[0].summary }}</text><view class="hero-bottom"><text>{{ featured[0].stats.participants }} {{ c.participants }}</text></view></view></button>
     <view v-if="featured.length>1" class="dots"><button v-for="(item,index) in featured" :key="item.id" :aria-label="c.featured+' '+(index+1)" :aria-pressed="featuredIndex===index" @click="featuredIndex=index"><view :class="{selected:featuredIndex===index}"/></button></view>
    </view>
    <view class="block-heading list-heading"><text>{{ c.discover }}</text></view>
    <view class="filter-bar"><scroll-view scroll-x :show-scrollbar="false"><view class="filters"><button v-for="key in ['all','active','upcoming','ended']" :key="key" :class="{selected:filter===key}" :aria-pressed="filter===key" @click="filter=key">{{ c[key] }}</button></view></scroll-view></view>
    <view v-if="!visible.length" class="state">{{ c.empty }}</view>
    <view v-else class="cards"><button v-for="item in visible" :key="item.id" class="event-row" @click="open(item)"><image :src="item.cover" mode="aspectFill"/><view class="copy"><view class="row-top"><text class="status">{{ c[item.phase] }}</text><view class="row-heat" @tap.stop="explainHeat"><uni-icons type="fire-filled" size="13" color="#b9954f"/><text>{{ item.stats.heat }}</text></view></view><text class="card-title">{{ item.title }}</text><text class="summary">{{ item.summary }}</text><text class="meta">{{ item.stats.participants }} {{ c.participants }} · {{ item.stats.posts }} {{ c.postCount }}</text><text v-if="item.fallback" class="fallback">{{ c.fallback }}{{ contentLanguageNames[item.locale] }}</text></view></button></view>
   </view>
  </view>
 </view>
</template>
<script setup>
import { computed, ref, watch, onBeforeUnmount } from 'vue'
import { currentLocale } from '@/utils/localeRuntime.js'
import { getToken } from '@/utils/auth.js'
import { getActivities, getMyActivities, editorialMessages, contentLanguageNames } from '@/utils/editorial.js'
const c=computed(()=>editorialMessages[currentLocale.value]||editorialMessages.en)
const items=ref([]),filter=ref('all'),loading=ref(false),failed=ref(false),section=ref('discover'),featuredIndex=ref(0)
const featured=computed(()=>items.value.filter(item=>item.featured && item.phase!=='ended'))
const visible=computed(()=>items.value.filter(item=>filter.value==='all'||item.phase===filter.value))
const joined=ref([]),mineLoading=ref(false),mineFailed=ref(false),mineTotal=ref(0),signedIn=ref(!!getToken())
let revision=0,mineRevision=0,minePage=1,mineLoaded=false
function normalized(item){return {...item,stats:item.stats||{heat:0,participants:0,posts:0}}}
async function load(){const id=++revision;loading.value=true;failed.value=false;try{const data=await getActivities(currentLocale.value);if(id===revision){items.value=(data.items||[]).map(normalized);featuredIndex.value=0}}catch(_){if(id===revision)failed.value=true}finally{if(id===revision)loading.value=false}}
function resetMine(){mineRevision++;minePage=1;joined.value=[];mineTotal.value=0;mineLoading.value=false;mineFailed.value=false;mineLoaded=false}
async function loadMine(){signedIn.value=!!getToken();if(!signedIn.value||mineLoading.value)return;const id=mineRevision;mineLoading.value=true;mineFailed.value=false;try{const data=await getMyActivities(currentLocale.value,minePage);if(id!==mineRevision)return;joined.value=[...joined.value,...data.items.map(normalized)];mineTotal.value=data.total;minePage++;mineLoaded=true}catch(_){if(id===mineRevision)mineFailed.value=true}finally{if(id===mineRevision)mineLoading.value=false}}
function switchSection(){section.value=section.value==='mine'?'discover':'mine';if(section.value==='mine'&&!mineLoaded)loadMine()}
function open(item,mine=false){if(item.available===false)return;uni.navigateTo({url:'/pages/activity/detail?id='+encodeURIComponent(item.id)+(mine?'&mine=1':'')})}
function explainHeat(){uni.showToast({title:c.value.heatHint,icon:'none',duration:4000})}
function login(){uni.navigateTo({url:'/pages/login/login360'})}
async function refresh(){if(section.value==='mine'){resetMine();await loadMine()}else await load()}
function clearPrivateCache(){resetMine();signedIn.value=false}
uni.$on('auth-session-changed',clearPrivateCache)
watch(currentLocale,()=>{resetMine();load();if(section.value==='mine')loadMine()},{immediate:true});onBeforeUnmount(()=>{revision++;mineRevision++;uni.$off('auth-session-changed',clearPrivateCache)})
defineExpose({refresh})
</script>
<style scoped>
.events{max-width:560px;margin:auto;padding:16px 18px 30px;color:#302e29}.section-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.heading-copy{flex:1;min-width:0}.eyebrow{display:block;font-size:9px;letter-spacing:2px;color:#a68a52}.heading{display:block;font-size:25px;font-weight:700;line-height:1.4;margin-top:5px}.mine-button{display:flex;align-items:center;gap:6px;flex-shrink:0;max-width:48%;padding:11px 12px;margin:0;border:1px solid #e9e1d1;border-radius:22px;background:#fffaf0;color:#8d713b;font-size:12px;line-height:1.5;text-align:left}.lead{display:block;font-size:13px;line-height:1.6;color:#938b7d;margin:10px 0 24px}.block-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:16px;font-weight:650;margin-bottom:12px}.count{font-size:11px;font-weight:400;color:#a29a8a}.featured-swiper{height:310px}.hero-card{position:relative;width:100%;height:310px;border-radius:24px;overflow:hidden;margin:0;padding:0;text-align:left;background:#e7e2d8;color:#fff}.hero-card>image,.hero-shade{position:absolute;inset:0;width:100%;height:100%}.hero-shade{background:linear-gradient(180deg,rgba(29,25,17,.12),rgba(29,25,17,.02) 30%,rgba(29,25,17,.76) 100%)}.hero-top{position:absolute;top:16px;left:16px;right:16px;display:flex;justify-content:space-between;align-items:flex-start;gap:8px;font-size:11px;line-height:1.6}.hero-status{padding:5px 10px;background:#fff4dc;color:#7d602d;border-radius:20px}.heat{display:flex;align-items:center;gap:4px;padding:5px 9px;border-radius:20px;background:rgba(25,23,17,.34);color:#fff3cf}.hero-copy{position:absolute;bottom:18px;left:20px;right:20px}.hero-title{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:24px;font-weight:650;line-height:1.35}.hero-summary{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin-top:9px;font-size:12px;line-height:1.6;color:#f0eadf}.hero-bottom{display:flex;align-items:center;justify-content:space-between;margin-top:15px;font-size:11px;color:#f3e8d5}.dots{display:flex;justify-content:center;margin:6px 0}.dots button{display:flex;justify-content:center;align-items:center;width:30px;height:28px;padding:0;margin:0;background:transparent}.dots view{width:5px;height:5px;background:#d8d2c4;border-radius:8px}.dots .selected{width:18px;background:#c2a052}.list-heading{margin-top:24px}.filter-bar{margin-bottom:18px}.filters{display:flex;gap:8px}.filters button{flex-shrink:0;padding:8px 14px;border-radius:22px;background:#fff;font-size:12px;line-height:1.7;margin:0;white-space:nowrap;color:#918a7b}.filters .selected{background:#efe3c2;color:#7d632d}.cards{display:flex;flex-direction:column;gap:12px}.event-row{display:flex;align-items:stretch;gap:14px;width:100%;padding:12px;margin:0;background:#fff;border-radius:21px;text-align:left;line-height:1.6;color:#302e29}.event-row>image{width:96px;height:118px;flex-shrink:0;border-radius:14px;background:#ebe7de}.copy{flex:1;min-width:0}.row-top{display:flex;align-items:center;justify-content:space-between;gap:8px}.status{font-size:10px;color:#a1844b}.row-heat{display:flex;align-items:center;gap:3px;font-size:11px;color:#a1844b}.card-title{display:block;font-size:16px;font-weight:650;line-height:1.4;margin:5px 0;overflow-wrap:anywhere}.summary{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:11px;color:#999080;line-height:1.6}.meta{display:block;font-size:10px;color:#a39885;margin-top:9px}.fallback{display:block;font-size:10px;color:#aaa08e}.row-link{display:block;color:#aa8845;font-size:12px;margin-top:10px}.state{padding:40px 15px;text-align:center;color:#938b7d;line-height:1.7}.state>text{display:block;margin:12px 0}.state button,.load-more{font-size:13px;background:#efe3c2;border-radius:22px;padding:9px 18px;line-height:1.6;margin:14px auto 0;max-width:260px;color:#7d632d}button::after{border:0}button:active{opacity:.9}.event-row[disabled]{opacity:.7;background:#f5f3ee}@media(max-width:360px){.events{padding-left:12px;padding-right:12px}.event-row{gap:10px}.event-row>image{width:78px;height:110px}.hero-title{font-size:22px}.mine-button{padding:9px;font-size:11px}}
</style>
